package com.fitpulse.repository; import com.fitpulse.model.entity.*; import com.fitpulse.model.enums.ContentStatus; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface ReviewRepository extends JpaRepository<Review,Long>{List<Review> findAllByGymAndStatusOrderByCreatedAtDesc(Gym gym,ContentStatus status); Optional<Review> findByGymAndUser(Gym gym,User user); long countByStatus(ContentStatus status); @Query("select coalesce(avg(r.rating),0) from Review r where r.gym=:gym and r.status=com.fitpulse.model.enums.ContentStatus.PUBLISHED") double averageForGym(Gym gym);}
